1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { existsSync, readFileSync } from 'node:fs';
4	import { execFile } from 'node:child_process';
5	import { fileURLToPath } from 'node:url';
6	import { dirname, join } from 'node:path';
7	import { validateTaskDeclaration } from '../../../../claudinite-tasks/shared-code/task-contract.mjs';
8	import declJson from '../../../tasks/fleet-pack-seeds/task.json' with { type: 'json' };
9	import rosterJson from '../../../tasks/fleet-roster/task.json' with { type: 'json' };
10	import { evaluatePrecondition } from '../../../../claudinite-tasks/shared-code/preconditions.mjs';
11	import { normalizeTaskDeclaration } from '../../../../claudinite-tasks/task-contract.mjs';
12	// The loader's door: the JSON says what is particular to the task, the defaults are the contract's.
13	const decl = normalizeTaskDeclaration(declJson);
14	const roster = normalizeTaskDeclaration(rosterJson);
15	
16	// The claudinite-fleet-sheepdog pack's fleet-pack-seeds task: the enforcer converging the pack
17	// declarations this fleet standardizes on. Same agentless shape as the other
18	// sweeps and locked down the same way — the declaration satisfies the contract the
19	// scheduler and executor both read, and the worker INVOKES the sweep rather than
20	// reimplementing it (a copy would rot against check-fleet-pack-seeds.mjs).
21	
22	const packRoot = join(dirname(fileURLToPath(import.meta.url)), '../../../../../packs/claudinite-fleet-sheepdog');
23	const taskDir = join(packRoot, 'tasks/fleet-pack-seeds');
24	const workerSrc = readFileSync(join(taskDir, 'worker.mjs'), 'utf8');
25	const sweepSrc = readFileSync(join(taskDir, 'check-fleet-pack-seeds.mjs'), 'utf8');
26	
27	// --- the declaration ----------------------------------------------------------
28	
29	test('fleet-pack-seeds: the declaration satisfies the task contract', () => {
30	  assert.deepEqual(validateTaskDeclaration(decl), []);
31	});
32	
33	test('fleet-pack-seeds: daily, agentless, and ceilinged at "none" — its write goes to OTHER repos', () => {
34	  assert.equal(decl.id, 'fleet-pack-seeds');      // must match its directory name (discover.mjs)
35	  // A member becomes writable the moment its nightly converge vendors the pack; daily
36	  // is what turns that into "the next morning".
37	  assert.equal(decl.frequency, 'daily');
38	  assert.equal(decl.agent_model, 'none');
39	  // Not a contradiction with a sweep that writes: the ceiling describes what a task may
40	  // do to its OWN repo, and this one opens no PR here at all.
41	  assert.equal(decl.expected_outcome, 'none');
42	  // `['none']`, not an empty signal list: nothing repo-side predicts this task's
43	  // answer, and the declaration says so in the one word for it.
44	  assert.deepEqual(decl.preconditions, ['none']);
45	});
46	
47	test('fleet-pack-seeds: an ordinary pack task — not wired as a fleet mechanism', () => {
48	  // Same classification the other sweeps carry (per-project-scheduling DESIGN §6): the
49	  // cross-repo reach is in the implementation, never in the wiring.
50	  assert.equal(decl.session_scope, undefined);
51	  assert.deepEqual(decl.preconditions, ['none']);   // no `fleet` condition either
52	});
53	
54	test('fleet-pack-seeds: the sweep is the code_work, bounded and task-local', () => {
55	  assert.equal(decl.code_work, 'node worker.mjs');
56	  assert.ok(!decl.code_work.includes('..'));   // contract: no traversal out of the task dir
57	  assert.ok(Number.isInteger(decl.code_work_timeout) && decl.code_work_timeout > 0);
58	  assert.ok(existsSync(join(taskDir, 'worker.mjs')));
59	  assert.equal(decl.agent_instructions, undefined);   // vestigial field dropped: none task, no agent to instruct
60	});
61	
62	test('fleet-pack-seeds: one fleet secret, and one place the grant is stated', () => {
63	  assert.deepEqual(decl.code_work_required_secrets, ['FLEET_GITHUB_TOKEN']);
64	  assert.deepEqual(decl.code_work_required_secrets, roster.code_work_required_secrets);
65	  // The sweep needs a scope the read-only ones never did, and says so — but it renders
66	  // the GRANT from fleet-token.mjs rather than stating its own subset, which is what
67	  // let a fleet run for two days short one permission (#1030).
68	  assert.match(sweepSrc, /missingFleetTokenError\('fleet-pack-seeds'/);
69	});
70	
71	test('fleet-pack-seeds: fires unconditionally, with a reason', () => {
72	  const v = evaluatePrecondition({ decl }, {});
73	  assert.equal(v.run, true);
74	  assert.match(v.reason, /\S/);
75	});
76	
77	// --- the worker delegates to the sweep ----------------------------------------
78	
79	test('fleet-pack-seeds: the worker imports the pack\'s sweep instead of reimplementing it', () => {
80	  assert.match(workerSrc, /from '\.\/check-fleet-pack-seeds\.mjs'/);
81	  for (const marker of ['/user/repos', 'classifySeed', 'parseSheepdogConfig', 'withSeeds']) {
82	    assert.ok(!workerSrc.includes(marker), `worker.mjs should not reimplement the sweep (found ${marker})`);
83	  }
84	});
85	
86	test('fleet-pack-seeds: running the worker reaches the sweep, and its failure exits non-zero', async () => {
87	  // Behavioural, no network: with no FLEET_GITHUB_TOKEN the sweep throws before its
88	  // first fetch, so the message on stderr proves the worker actually got into
89	  // check-fleet-pack-seeds.mjs — and the non-zero exit is the escalation path (the
90	  // scheduler converges a failed code-work subprocess to a `needs-human` issue).
91	  const env = { ...process.env, GITHUB_REPOSITORY: 'acme/claudinite-fleet-sheepdog' };
92	  delete env.FLEET_GITHUB_TOKEN;
93	  const { code, stderr } = await new Promise((resolve) => {
94	    execFile(process.execPath, ['worker.mjs'], { cwd: taskDir, env }, (err, _out, errOut) => {
95	      resolve({ code: err ? err.code : 0, stderr: errOut });
96	    });
97	  });
98	  assert.equal(code, 1);
99	  assert.match(stderr, /FLEET_GITHUB_TOKEN is not set/);
100	});
101	
102	// --- it stays in its own lane -------------------------------------------------
103	
104	test('fleet-pack-seeds: names no pack — every id comes from the fleet\'s own config', () => {
105	  // The constraint that keeps the enforcer from becoming a second place packs are
106	  // known. The sweep carries the mechanism; the fleet that declares this pack supplies
107	  // which packs, in its own `packSeeds`.
108	  const packSrc = [sweepSrc, workerSrc, readFileSync(join(taskDir, 'task.json'), 'utf8'),
109	    readFileSync(join(packRoot, 'fleet-config.mjs'), 'utf8')].join('\n');
110	  for (const known of ['claude-code-web-users-support', 'UserPreferencesStore', 'preferences']) {
111	    assert.ok(!packSrc.includes(known), `the claudinite-fleet-sheepdog pack must not name "${known}"`);
112	  }
113	  assert.match(sweepSrc, /packSeeds/);
114	});
115	
116	test('fleet-pack-seeds: the only sweep that writes to a member, and it reaches up for what is shared', () => {
117	  // Each sweep lives IN its own task folder and reaches UP for what is shared — never
118	  // sideways into another task's folder, and never with a private copy.
119	  assert.match(sweepSrc, /from '\.\.\/\.\.\/fleet-api\.mjs'/);
120	  assert.match(sweepSrc, /from '\.\.\/\.\.\/fleet-config\.mjs'/);
121	  assert.ok(!/from '\.\.\/[a-z-]+\/check-fleet/.test(sweepSrc), 'a sweep must not import another task\'s sweep');
122	  // No issue label of its own: the finding IS the fix, and it is applied. A label here
123	  // would be a third issue stream converging on a condition nothing reports.
124	  assert.ok(!/const LABEL =/.test(sweepSrc));
125	  // The write is the fleet-api primitive, not a hand-rolled PUT — one place in the pack
126	  // can change another repo.
127	  assert.ok(!/method: 'PUT'/.test(sweepSrc), 'the write goes through fleet-api\'s putFile');
128	  assert.match(sweepSrc, /putFile\(gh, r\.full_name/);
129	});

