13	// The claudinite-fleet-sheepdog pack's fleet-add-missing-packs task on the FAN-OUT model (#749):
14	// the enforcer dispatches, the member executes. Everything asserted here is a
15	// property that, if it drifted, would either stop the task running at all or
16	// bring back the enforcer-side agent that failed in production.
17	
18	const taskDir = join(dirname(fileURLToPath(import.meta.url)), '../../../../../packs/claudinite-fleet-sheepdog/tasks/fleet-add-missing-packs');
19	const workerSrc = readFileSync(join(taskDir, 'worker.mjs'), 'utf8');
20	const briefSrc = readFileSync(join(taskDir, 'README.md'), 'utf8');
21	
22	test('fleet-add-missing-packs: the declaration satisfies the task contract', () => {
23	  assert.deepEqual(validateTaskDeclaration(decl), []);
24	});
25	
26	test('fleet-add-missing-packs: weekly, agentless, outcome none — the agent is the MEMBER\'s', () => {
27	  assert.equal(decl.id, 'fleet-add-missing-packs');   // must match its directory name (discover.mjs)
28	  // A repo's SHAPE is slow-moving; a daily sweep would re-ask a question whose answer
29	  // cannot have changed.
30	  assert.equal(decl.frequency, 'weekly');
31	  // The properties the fan-out model hangs on: no agent HERE (the first design's
32	  // enforcer-side agent stage failed in production — its executor is scoped to the
33	  // enforcer repo alone), and no PR here either. What only a repo edit can finish is
34	  // the member's adopt-requested-packs task, which opens the PR and lands it unattended THERE (#1453).
35	  assert.equal(decl.agent_model, 'none');
36	  assert.equal(decl.expected_outcome, 'none');
37	  assert.equal(decl.agent_instructions, undefined);
38	  // `['none']`, not an empty signal list: nothing repo-side predicts this task's
39	  // answer, and the declaration says so in the one word for it.
40	  assert.deepEqual(decl.preconditions, ['none']);
41	});
42	
43	test('fleet-add-missing-packs: declares no session scope — nothing agentic runs here at all', async () => {
44	  assert.equal(decl.session_scope, undefined);
45	  const { default: pack } = await import('../../../../../packs/claudinite-fleet-sheepdog/pack.mjs');
46	  assert.equal(pack.sessionScope, undefined);   // and no pack-level spelling either
47	});
