49	test('fleet-add-missing-packs: code_work is bounded, task-local, and SENDS both parameters', () => {
50	  // No defaults anywhere (params.mjs): the declaration is where a reader looks first
51	  // to learn what the cadence does, so what the cadence does is written here, and no
52	  // call site can reach the whole fleet by omission.
53	  assert.match(decl.code_work, /^node worker\.mjs /);
54	  assert.match(decl.code_work, /--scan-for-needed-packs=true/);
55	  assert.match(decl.code_work, /--repos=all-covered-members/);
56	  assert.ok(!decl.code_work.includes('..'));   // contract: no traversal out of the task dir
57	  assert.ok(Number.isInteger(decl.code_work_timeout) && decl.code_work_timeout > 0);
58	  assert.ok(existsSync(join(taskDir, 'worker.mjs')));
59	});
