61	test('fleet-add-missing-packs: the precondition fires unconditionally and says why', () => {
62	  // Every input lives outside this repo, so no collector signal can predict the
63	  // answer; the honest declaration is "always run, and no-op cheaply".
64	  const v = evaluatePrecondition({ decl }, {});
65	  assert.equal(v.run, true);
66	  assert.match(v.reason, /\S/);
67	});
