69	test('fleet-add-missing-packs: the worker invokes each half rather than reimplementing it', () => {
70	  // A copy of either half inside the worker would rot against the module it copied.
71	  // What the worker DOES own is what both halves need and neither may hold privately:
72	  // the parameters, the corpus, the enumeration, and the firing loop.
73	  assert.match(workerSrc, /from '\.\/scan-for-needed-packs\.mjs'/);
74	  assert.match(workerSrc, /from '\.\/force-add-packs\.mjs'/);
75	  assert.match(workerSrc, /from '\.\/params\.mjs'/);
76	});
