78	test('fleet-add-missing-packs: the worker fires member schedulers and requests no agent of its own', () => {
79	  // The fan-out contract, in code: the nudge dispatch, and the
80	  // conditional-handoff machinery gone — a request file written here would be the old
81	  // model growing back.
82	  assert.match(workerSrc, /fireScheduler/);
83	  assert.match(workerSrc, /adopt-requested-packs/);
84	  assert.ok(!workerSrc.includes('CLAUDINITE_REQUEST_AGENT'));
85	});
