87	test('fleet-add-missing-packs: the brief records the fan-out and the force\'s total refusal', () => {
88	  assert.match(briefSrc, /adopt-requested-packs/);
89	  assert.match(briefSrc, /refuses itself entirely/);
90	  assert.match(briefSrc, /interview/i);
91	  // The brief must say where the agentic work went, so a reader does not hunt for an
92	  // agent stage this task no longer has.
93	  assert.match(briefSrc, /runs no agent/);
